-- SEOK HUB: execute o arquivo completo para habilitar o auto restart opcional.
local source=[========[local SELF_SOURCE = ... -- Recebe o proprio codigo para reabrir apos teleport.
-- Verificacao de compatibilidade antes de qualquer GUI, wallpaper ou extras.
do
    if not game:IsLoaded() then game.Loaded:Wait() end
    local storage = game:GetService("ReplicatedStorage")
    local function supportsCloning()
        local events = storage:FindFirstChild("Events")
        if not events then return false end
        local catalog = events:FindFirstChild("CatalogGuiRemote")
        local outfits = events:FindFirstChild("SavedOutfitsRemote")
        return catalog ~= nil and catalog:IsA("RemoteFunction")
            and outfits ~= nil and outfits:IsA("RemoteFunction")
    end
    -- Pequena tolerancia para os componentes chegarem ao cliente.
    local deadline = os.clock() + 5
    while not supportsCloning() and os.clock() < deadline do task.wait(0.2) end
    if not supportsCloning() then
        local pg = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
        local previous = pg:FindFirstChild("SeokUnsupportedNotice")
        if previous then previous:Destroy() end
        local screen = Instance.new("ScreenGui")
        screen.Name = "SeokUnsupportedNotice"
        screen.ResetOnSpawn = false
        screen.DisplayOrder = 100000
        screen.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        local box = Instance.new("Frame")
        box.AnchorPoint = Vector2.new(1,1)
        box.Position = UDim2.new(1,-18,1,-18)
        box.Size = UDim2.new(0.9,0,0,120)
        box.BackgroundColor3 = Color3.fromRGB(47,16,25)
        box.BorderSizePixel = 0
        box.Parent = screen
        local limit = Instance.new("UISizeConstraint")
        limit.MaxSize = Vector2.new(380,120)
        limit.Parent = box
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0,12)
        corner.Parent = box
        local stroke = Instance.new("UIStroke")
        stroke.Color = Color3.fromRGB(244,91,116)
        stroke.Parent = box
        local title = Instance.new("TextLabel")
        title.BackgroundTransparency = 1
        title.Position = UDim2.fromOffset(16,12)
        title.Size = UDim2.new(1,-32,0,24)
        title.Font = Enum.Font.GothamBold
        title.TextSize = 16
        title.TextColor3 = Color3.fromRGB(244,91,116)
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.Text = "JOGO NÃO SUPORTADO"
        title.Parent = box
        local message = Instance.new("TextLabel")
        message.BackgroundTransparency = 1
        message.Position = UDim2.fromOffset(16,43)
        message.Size = UDim2.new(1,-32,0,64)
        message.Font = Enum.Font.GothamMedium
        message.TextSize = 14
        message.TextWrapped = true
        message.TextXAlignment = Enum.TextXAlignment.Left
        message.TextColor3 = Color3.fromRGB(255,240,243)
        message.Text = "Este jogo não suporta o SEOK'S CLONING HUB. Abra o Catalog Avatar Creator para usar o script."
        message.Parent = box
        screen.Parent = pg
        task.delay(8,function() screen:Destroy() end)
        return
    end
end

-- SEOK Halloween 1.0. Substitui a versao anterior; execute este arquivo inteiro.
-- EXTRAS contem o TXT anexado e so o executa quando voce clicar.
do
    local pg = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
    local existing = pg:FindFirstChild("SeokHalloweenHub")
    if existing then
        local shutdown = existing:FindFirstChild("Shutdown")
        if shutdown then shutdown:Fire() else existing:Destroy() end
    end
end
-- SEOK'S CLONING HUB | abertura visual, seguida do codigo original.
-- Wallpaper incorporado. Requer writefile + getcustomasset (ou getsynasset).
-- Opcional: substitua por um asset de imagem seu para dispensar essas funcoes.
do
    local WALLPAPER_ASSET = "" -- Exemplo: rbxassetid://123456789
    local DURATION = 6
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")
    local player = Players.LocalPlayer
    assert(player, "Execute no cliente.")
    local parent = player:WaitForChild("PlayerGui")
    if parent:FindFirstChild("SeokCloningLoading") then return end
    local gui = Instance.new("ScreenGui")
    gui.Name = "SeokCloningLoading"
    gui.IgnoreGuiInset = true
    gui.ResetOnSpawn = false
    gui.DisplayOrder = 100000
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    gui.Parent = parent
    -- MUSICA DO CARREGAMENTO: altere apenas o numero abaixo.
    local LOADING_MUSIC_ID = "134959834418523"
    local LOADING_FADE_SECONDS = 0.8
    local lofi = Instance.new("Sound")
    lofi.Name = "LoadingLofi"
    lofi.SoundId = "rbxassetid://" .. LOADING_MUSIC_ID
    lofi.Looped = true
    lofi.Volume = 0
    lofi.Parent = game:GetService("SoundService")

    local ok, err = xpcall(function()
        local function new(class, props, owner)
            local object = Instance.new(class)
            for key, value in pairs(props) do object[key] = value end
            object.Parent = owner
            return object
        end
        local root = new("Frame", {
            Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(32,10,17),
            BorderSizePixel = 0, ClipsDescendants = true, Active = true,
        }, gui)
        local imageAsset = WALLPAPER_ASSET
        if imageAsset == "" then
            local loaded, result = pcall(function()
                local register = getcustomasset or getsynasset
                assert(type(writefile) == "function" and type(register) == "function",
                    "Wallpaper precisa de writefile e getcustomasset/getsynasset; ou configure WALLPAPER_ASSET.")
                local encoded = ""
                local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
                local lookup = {}
                for i = 1, #alphabet do lookup[string.byte(alphabet, i)] = i - 1 end
                local chunks = {}
                for i = 1, #encoded, 4 do
                    local a, b, c, d = string.byte(encoded, i, i + 3)
                    local n = lookup[a] * 262144 + lookup[b] * 4096
                        + (lookup[c] or 0) * 64 + (lookup[d] or 0)
                    local s = string.char(math.floor(n / 65536))
                    if c ~= 61 then s = s .. string.char(math.floor(n / 256) % 256) end
                    if d ~= 61 then s = s .. string.char(n % 256) end
                    chunks[#chunks + 1] = s
                    if i % 131072 == 1 then task.wait() end
                end
                local filename = "seok_cloning_wallpaper.png"
                writefile(filename, table.concat(chunks))
                return register(filename)
            end)
            if loaded then imageAsset = result else warn("[SEOK] " .. tostring(result)) end
        end
        -- Blur visual aproximado: media de nove copias deslocadas da mesma textura.
        -- BlurEffect nao desfoca ImageLabels; aqui apenas o wallpaper e suavizado.
        local offsets = {{0,0},{-3,-3},{0,-3},{3,-3},{-3,0},{3,0},{-3,3},{0,3},{3,3}}
        local wallpaper
        for i, offset in ipairs(offsets) do
            local layer = new("ImageLabel", {
                Name = "Wallpaper", AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.new(0.5, offset[1], 0.5, offset[2]),
                Size = UDim2.new(1, 16, 1, 16), BackgroundTransparency = 1,
                Image = imageAsset, ScaleType = Enum.ScaleType.Crop,
                ImageTransparency = 1 - 1 / i, ZIndex = 1,
            }, root)
            wallpaper = wallpaper or layer
        end
        new("Frame", {Size = UDim2.fromScale(1,1), BorderSizePixel = 0,
            BackgroundColor3 = Color3.fromRGB(20,5,10), BackgroundTransparency = 0.38,
            ZIndex = 2}, root)
        local function label(text, pos, size, fontSize, color)
            return new("TextLabel", {Text = text, Position = pos, Size = size,
                BackgroundTransparency = 1, TextColor3 = color or Color3.fromRGB(255,240,243),
                Font = Enum.Font.GothamMedium, TextSize = fontSize, ZIndex = 3,
                TextWrapped = true}, root)
        end
        local title = label("SEOK'S CLONING HUB", UDim2.fromScale(0.08,0.42),
            UDim2.fromScale(0.84,0.12), 44)
        title.Font = Enum.Font.GothamBold
        title.TextScaled = true
        new("UITextSizeConstraint", {MaxTextSize = 48, MinTextSize = 14}, title)
        title.TextStrokeTransparency = 0.8
        label("By: xLgfb_1357BRx", UDim2.fromScale(0.1,0.55), UDim2.fromScale(0.8,0.04), 14,
            Color3.fromRGB(255,180,192))
        local status = label("Preparing interface...", UDim2.new(0.07,0,1,-108),
            UDim2.new(0.70,0,0,24), 14)
        status.TextXAlignment = Enum.TextXAlignment.Left
        local percent = label("0%", UDim2.new(0.79,0,1,-108), UDim2.new(0.14,0,0,24), 14)
        percent.TextXAlignment = Enum.TextXAlignment.Right
        local track = new("Frame", {Position = UDim2.new(0.07,0,1,-70),
            Size = UDim2.new(0.86,0,0,6), BorderSizePixel = 0,
            BackgroundColor3 = Color3.fromRGB(255,255,255), BackgroundTransparency = 0.8,
            ClipsDescendants = true, ZIndex = 3}, root)
        new("UICorner", {CornerRadius = UDim.new(0,3)}, track)
        local fill = new("Frame", {Size = UDim2.fromScale(0,1), BorderSizePixel = 0,
            BackgroundColor3 = Color3.fromRGB(244,91,116), ZIndex = 4}, track)
        new("UICorner", {CornerRadius = UDim.new(0,3)}, fill)
        new("UIGradient", {Color = ColorSequence.new(Color3.fromRGB(244,91,116),
            Color3.fromRGB(255,180,192))}, fill)
        -- Espera limitada para a textura; as etapas seguintes sao apenas decorativas.
        local deadline = os.clock() + 3
        while imageAsset ~= "" and not wallpaper.IsLoaded and os.clock() < deadline do task.wait(0.05) end
        local stages = {"Loading Workspace...", "Loading Players...", "Loading Avatar Data...",
            "Preparing Cloning Interface...", "Finalizing...", "Ready!"}
        -- O som comeca junto da animacao da barra.
        lofi:Play()
        TweenService:Create(lofi,TweenInfo.new(0.35),{Volume=0.18}):Play()
        local start = os.clock()
        while gui.Parent do
            local progress = math.clamp((os.clock() - start) / DURATION, 0, 1)
            fill.Size = UDim2.fromScale(progress, 1)
            percent.Text = tostring(math.floor(progress * 100)) .. "%"
            status.Text = stages[math.min(#stages, math.floor(progress * #stages) + 1)]
            if progress >= 1 then break end
            task.wait(0.03)
        end
        task.wait(0.35)
        -- O mesmo intervalo sincroniza o fade visual e o volume.
        TweenService:Create(lofi,TweenInfo.new(LOADING_FADE_SECONDS),{Volume=0}):Play()
        for _, object in ipairs(gui:GetDescendants()) do
            local goal = {}
            if object:IsA("GuiObject") then goal.BackgroundTransparency = 1 end
            if object:IsA("TextLabel") then goal.TextTransparency = 1; goal.TextStrokeTransparency = 1 end
            if object:IsA("ImageLabel") then goal.ImageTransparency = 1 end
            if next(goal) then TweenService:Create(object, TweenInfo.new(LOADING_FADE_SECONDS), goal):Play() end
        end
        task.wait(LOADING_FADE_SECONDS + 0.05)
    end, function(message) return tostring(message) end)
    lofi:Stop()
    lofi:Destroy()
    gui:Destroy()
    if not ok then warn("[SEOK] Falha na abertura: " .. tostring(err)) end
end


local plrs = game:GetService("Players")
local rs = game:GetService("ReplicatedStorage")


local function rgb(c) return {
		r = math.floor(c.R * 255),
		g = math.floor(c.G * 255),
		b = math.floor(c.B * 255),
		IsRGBTable = true}
end

local function vector(v)
	return {
		X = v.X,
		Y = v.Y,
		Z = v.Z,
		Vector3 = true
	}
end

local function getLayeredAccessories(desc)
	local result = {}

	for _, accessory in desc:GetAccessories(true) do
		if accessory.IsLayered then
			table.insert(result, {
				Rotation = vector(accessory.Rotation),
				AssetId = accessory.AssetId,
				AccessoryType = accessory.AccessoryType.Name,
				Position = vector(accessory.Position),
				Order = accessory.Order,
				IsLayered = true,
				Puffiness = accessory.Puffiness,
				Scale = vector(accessory.Scale)
			})
		end
	end
	       return result
end

local function copy(targetPlayer)
    local events = rs:FindFirstChild("Events")
    local theremote = events and events:FindFirstChild("CatalogGuiRemote")
    if not theremote then error("CatalogGuiRemote indisponivel neste jogo.") end
	if not targetPlayer or not targetPlayer.Character then return end

	local h = targetPlayer.Character:FindFirstChildOfClass("Humanoid")
	if not h then return end

	local desc = h:GetAppliedDescription()

	local wear = {{
		["Properties"] = {
			["WalkAnimation"] = desc.WalkAnimation,
			["MoodAnimation"] = desc.MoodAnimation,
			["Face"] = desc.Face,
			["ProportionScale"] = desc.ProportionScale,
			["ClimbAnimation"] = desc.ClimbAnimation,
			["Shirt"] = desc.Shirt,
			["FaceAccessory"] = desc.FaceAccessory,
			["RightArmColor"] = rgb(desc.RightArmColor),
			["TorsoColor"] = rgb(desc.TorsoColor),
			["RightLegColor"] = rgb(desc.RightLegColor),
			["LeftLegColor"] = rgb(desc.LeftLegColor),
			["LeftArmColor"] = rgb(desc.LeftArmColor),
			["HeadColor"] = rgb(desc.HeadColor),
			["HairAccessory"] = desc.HairAccessory,
			["RightArm"] = desc.RightArm,
			["Head"] = desc.Head,
			["FallAnimation"] = desc.FallAnimation,
			["DepthScale"] = desc.DepthScale,
			["LeftArm"] = desc.LeftArm,
			["HeightScale"] = desc.HeightScale,
			["LeftLeg"] = desc.LeftLeg,
			["WidthScale"] = desc.WidthScale,
			["BodyTypeScale"] = desc.BodyTypeScale,
			["RunAnimation"] = desc.RunAnimation,
			["Pants"] = desc.Pants,
			["WaistAccessory"] = desc.WaistAccessory,
			["LayeredAccessories"] = getLayeredAccessories(desc),
			["AccessoryRefinements"] = {},
			["ShouldersAccessory"] = desc.ShouldersAccessory,
			["NeckAccessory"] = desc.NeckAccessory,
			["HatAccessory"] = desc.HatAccessory,
			["FrontAccessory"] = desc.FrontAccessory,
			["BackAccessory"] = desc.BackAccessory,
			["SwimAnimation"] = desc.SwimAnimation,
			["IdleAnimation"] = desc.IdleAnimation,
			["Torso"] = desc.Torso,
			["HeadScale"] = desc.HeadScale,
			["JumpAnimation"] = desc.JumpAnimation,
			["GraphicTShirt"] = desc.GraphicTShirt,
			["RightLeg"] = desc.RightLeg
		},
		["Action"] = "CreateAndWearHumanoidDescription",
		["RigType"] = h.RigType
	}}
theremote:InvokeServer(unpack(wear))

	rs.Events.SavedOutfitsRemote:InvokeServer({
		OutfitName = "[ CLONADO PELO SEOKJIN ]",
		Configs = {},
		Action = "CreateNewOutfit"
	})
end



