end)
local watched={}
local function proximity(target,character)
    local hrp=character:WaitForChild("HumanoidRootPart",10)
    if not alive or not hrp or target.Character~=character then return end
    local legacy=hrp:FindFirstChild("CopyPrompt")
    if legacy then legacy:Destroy() end
    local prompt=new("ProximityPrompt",{Name="CopyPrompt",MaxActivationDistance=15,
        ObjectText="JOGADOR ALVO: "..target.Name,ActionText="Clonar!",RequiresLineOfSight=false,
        Enabled=cloning},hrp)
    prompts[prompt]=true
    connect(prompt.Triggered,function()
        if not alive or not cloning or copying then return end
        copying=true
        notice.Text="Clonando "..target.Name.."..."
        local success,reason=pcall(copy,target)
        copying=false
        if alive then notice.Text=success and "Visual de "..target.Name.." aplicado." or "Falha ao clonar. Veja o console." end
        if not success then warn("[SEOK] "..tostring(reason)) end
    end)
    connect(prompt.Destroying,function() prompts[prompt]=nil end)
end
local function setup(target)
    if target==Players.LocalPlayer or watched[target] then return end
    watched[target]=true
    connect(target.CharacterAdded,function(character) task.spawn(proximity,target,character) end)
    if target.Character then task.spawn(proximity,target,target.Character) end
end
connect(Players.PlayerAdded,setup)
connect(Players.PlayerRemoving,function(target) watched[target]=nil end)
for _, target in ipairs(Players:GetPlayers()) do setup(target) end


